//! 🔗️ Original Store read guards retain registry and return-flag custody through funded closure.
use super::{SnapshotRead,SnapshotReadLeaseRegistry,SNAPSHOT_READ_LEASE_CAPACITY};
use semio_framework_value::{ValueError,ValueRefusalKind,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep},retirement::{RetireOwned,RetirementCursor,RetirementStep,shared::SharedControlledRetirement}};
use std::{mem::ManuallyDrop,sync::{Arc,atomic::{AtomicBool,Ordering}}};

fn arc_bytes<T>()->usize {std::alloc::Layout::new::<[usize;2]>().extend(std::alloc::Layout::new::<T>()).expect("Store read Arc layout").0.pad_to_align().size()}

struct SnapshotReadRetirement<T:RetireOwned+Sync> {
    read:ManuallyDrop<Option<SnapshotRead<T>>>,
    alias:ManuallyDrop<Option<SharedControlledRetirement<T>>>,
    returned:ManuallyDrop<Option<Arc<AtomicBool>>>,
    registry:ManuallyDrop<Option<Arc<SnapshotReadLeaseRegistry>>>,
    owned_registry:ManuallyDrop<Option<SnapshotReadLeaseRegistry>>,
}
impl<T:RetireOwned+Sync> SnapshotReadRetirement<T> {
    fn new(read:SnapshotRead<T>)->Self {Self{read:ManuallyDrop::new(Some(read)),alias:ManuallyDrop::new(None),returned:ManuallyDrop::new(None),registry:ManuallyDrop::new(None),owned_registry:ManuallyDrop::new(None)}}
    fn backing_bytes(&self)->Result<usize,ValueError>{
        self.owned_registry.as_ref().map_or(Ok(0),|registry|{
            let state=registry.state.try_lock().map_err(|_|ValueError::literal(ValueRefusalKind::InvariantViolated,"uniquely retained read registry state is unavailable"))?;
            state.slots.len().checked_mul(size_of::<super::SnapshotReadLeaseSlot>()).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"read registry backing layout overflow"))
        })
    }
    fn copy_demand(&self)->Result<usize,ValueError>{self.alias.as_ref().map_or(Ok(0),|alias|if alias.terminal_is_empty(){Ok(0)}else{alias.next_copy_byte_demand()})}
    fn capacity_demand(&self,copy:usize)->Result<usize,ValueError>{self.alias.as_ref().map_or(Ok(0),|alias|if alias.terminal_is_empty(){Ok(0)}else{alias.next_capacity_byte_demand(copy)})}
    fn release_demand(&self)->Result<usize,ValueError>{
        if self.read.as_ref().is_some_and(|read|read.owner.is_some()){return Ok(0);}
        if let Some(alias)=self.alias.as_ref(){return if alias.terminal_is_empty(){Ok(0)}else{alias.next_release_byte_demand()};}
        if self.read.is_some(){return Ok(0);}
        if self.returned.is_some(){return Ok(arc_bytes::<AtomicBool>());}
        if self.registry.is_some(){return Ok(arc_bytes::<SnapshotReadLeaseRegistry>());}
        self.backing_bytes()
    }
    fn depth_demand(&self)->Result<usize,ValueError>{
        if self.read.as_ref().is_some_and(|read|read.owner.is_some()){return Ok(1);}
        if let Some(alias)=self.alias.as_ref(){return if alias.terminal_is_empty(){Ok(0)}else{alias.next_depth_demand()};}
        if self.read.is_some()||self.returned.is_some()||self.registry.is_some(){return Ok(1);}
        Ok(usize::from(self.backing_bytes()?!=0))
    }
    fn step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{
        let empty=RetainedCloneProgress::default();
        if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(empty));}
        if grant.maximum_items==0{return Ok(RetainedCloneStep::Progress(empty));}
        if grant.maximum_depth<self.depth_demand()?{return Err(ValueError::literal(ValueRefusalKind::DepthLimit,"Store read closure exceeds admitted depth"));}
        if let Some(read)=self.read.as_mut(){if let Some(owner)=read.owner.take(){*self.alias=Some(SharedControlledRetirement::lease(owner));return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..empty}));}}
        if let Some(alias)=self.alias.as_mut(){
            if alias.terminal_is_empty(){*self.alias=None;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..empty}));}
            return alias.step(grant);
        }
        if let Some(mut read)=self.read.take(){
            if let Some(lease)=read.lease.take(){
                if !lease.returned.load(Ordering::Acquire){
                    lease.registry.returned.fetch_add(1,Ordering::AcqRel);
                    if lease.returned.compare_exchange(false,true,Ordering::AcqRel,Ordering::Acquire).is_err(){lease.registry.returned.fetch_sub(1,Ordering::AcqRel);}
                }
                *self.returned=Some(lease.returned);*self.registry=Some(lease.registry);
            }
            return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..empty}));
        }
        if let Some(returned)=self.returned.as_ref(){
            let bytes=arc_bytes::<AtomicBool>();if Arc::weak_count(returned)!=0||grant.maximum_release_bytes<bytes{return Ok(RetainedCloneStep::Progress(empty));}
            let released_bytes=if Arc::into_inner(self.returned.take().unwrap()).is_some(){bytes}else{0};
            return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes,..empty}));
        }
        if let Some(registry)=self.registry.as_ref(){
            let bytes=arc_bytes::<SnapshotReadLeaseRegistry>();if Arc::weak_count(registry)!=0||grant.maximum_release_bytes<bytes{return Ok(RetainedCloneStep::Progress(empty));}
            let released_bytes=if let Some(registry)=Arc::into_inner(self.registry.take().unwrap()){*self.owned_registry=Some(registry);bytes}else{0};
            return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes,..empty}));
        }
        if let Some(registry)=self.owned_registry.as_mut(){
            let state=registry.state.get_mut().map_err(|_|ValueError::literal(ValueRefusalKind::InvariantViolated,"owned read registry state is poisoned"))?;
            if state.free_len!=SNAPSHOT_READ_LEASE_CAPACITY||registry.returned.load(Ordering::Acquire)!=0{return Ok(RetainedCloneStep::Progress(empty));}
            let bytes=state.slots.len().checked_mul(size_of::<super::SnapshotReadLeaseSlot>()).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"read registry backing layout overflow"))?;
            if bytes>grant.maximum_release_bytes{return Ok(RetainedCloneStep::Progress(empty));}
            if bytes!=0{drop(std::mem::take(&mut state.slots));return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..empty}));}
            *self.owned_registry=None;
            return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..empty}));
        }
        Ok(RetainedCloneStep::Complete(empty))
    }
}
impl<T:RetireOwned+Sync> RetirementCursor for SnapshotReadRetirement<T> {
    fn close_step(&mut self,grant:RetainedCloneGrant)->RetirementStep{match self.step(grant){Err(error)=>RetirementStep::Failure(error),Ok(RetainedCloneStep::Complete(_))=>RetirementStep::Complete,Ok(RetainedCloneStep::Progress(progress))=>RetirementStep::Progress(progress)}}
    fn terminal_is_empty(&self)->bool{self.read.is_none()&&self.alias.is_none()&&self.returned.is_none()&&self.registry.is_none()&&self.owned_registry.is_none()}
    fn next_work_byte_demand(&self)->Result<usize,ValueError>{self.copy_demand()}
    fn allows_admitted_narrow_work(&self)->bool{true}
    fn next_birth_bytes(&self,copy:usize)->Option<usize>{self.capacity_demand(copy).ok()}
    fn next_close_byte_demand(&self)->Option<usize>{self.release_demand().ok()}
    fn next_depth_demand(&self)->Result<usize,ValueError>{self.depth_demand()}
    fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(size_of::<Self>())}
}
impl<T:RetireOwned+Sync> RetireOwned for SnapshotRead<T> {
    fn retirement(self)->Box<dyn RetirementCursor>{Box::new(SnapshotReadRetirement::new(self))}
    fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<SnapshotReadRetirement<T>>())}
    fn controlled_retirement_supported()->bool{T::controlled_retirement_supported()}
}
impl<T:RetireOwned+Sync> Drop for SnapshotReadRetirement<T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Store read custody requires full granted closure");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.read);ManuallyDrop::drop(&mut self.alias);ManuallyDrop::drop(&mut self.returned);ManuallyDrop::drop(&mut self.registry);ManuallyDrop::drop(&mut self.owned_registry);}}}}

